from save_review import save
save(1238,{6:'不过，在大远征和荷鲁斯之乱时期，收割者自动炮曾普遍装备于各阿斯塔特军团。它最初是为战术无畏装甲设计的支援武器，结构紧凑、射速很高，需要依靠终结者装甲的力量来稳定枪身，并承受强大后坐力。'},terms=[('Reaper Autocannon','收割者自动炮')])
save(1239,{2:'加速自动炮是一种重型自动炮。这类速射武器的炮弹初速远高于标准自动炮，因此既能有效打击移动目标，也能实现精准命中。',4:'原铸先锋部队中的压制者使用其小型版本。'},terms=[('Accelerator Autocannon','加速自动炮'),('Herakles Pattern','赫拉克勒斯型')])
save(1240,{2:'安维鲁斯短管自动炮是大远征和荷鲁斯之乱期间，帝国军刀反坦克车装备的一种自动炮。',4:'Sabre Tank Hunter with Anvilus Snub Autocannon 装备安维鲁斯短管自动炮的军刀反坦克车',6:'这种自动炮结构紧凑、威力强大，产自铸造世界安维鲁斯，素以性能胜过同类而闻名。短枪管与复杂的供弹系统使它既能容纳于突击战车的小型底盘内，又能提供出色的反装甲火力。'},notes={2:'Snub指短管型；原“斥责”误译，已与1237统一。'},terms=[('Anvilus Snub Autocannon','安维鲁斯短管自动炮'),('Anvilus','安维鲁斯')],title='安维鲁斯短管自动炮 Anvilus Snub Autocannon')
save(1241,{2:'伊卡洛斯风暴炮阵列是星际战士安装在追猎者载具上的防空武器系统。',4:'这一阵列由两座可独立转向的三管炮塔和一面大型雷达天线组成，能够同时跟踪、射击两个不同的空中目标。火炮射速很高，充裕的储弹空间使其能够向空中倾泻数百发实弹。',8:'伊卡洛斯风暴炮受一套沉思者阵列控制，该阵列由数名互相连接、各自执行单一任务的机仆组成。',14:'伊卡洛斯风暴炮阵列也可以独立部署，作为固定防空设施使用。'},notes={8:'servitor是机仆，不是服务器；slaved to指受控于，cogitator是沉思者计算装置。'},terms=[('Icarus Stormcannon Array','伊卡洛斯风暴炮阵列'),('Icarus Stormcannon','伊卡洛斯风暴炮')])
save(1242,{2:'利维坦风暴炮是星际战士利维坦攻城无畏机甲使用的重型武器。它专为利维坦研制，射程较短，由四门重型自动炮组成。'},terms=[('Leviathan Storm Cannon','利维坦风暴炮')])
save(1243,{2:'猛攻加特林炮是原铸星际战士使用的一种转管武器。',5:'猛攻加特林炮——安装于救赎者无畏机甲的动力拳和反重力战车。',7:'Onslaught Gatling Cannon 猛攻加特林炮',9:'猛攻重型加特林炮——更重型的改型，用作救赎者无畏机甲的主武器。',11:'Onslaught Heavy Gatling Cannon 猛攻重型加特林炮'},notes={2:'沿第644篇统一Onslaught为猛攻；原稿另译突击，保留原译文对照。'},terms=[('Onslaught Gatling Cannon','猛攻加特林炮'),('Onslaught Heavy Gatling Cannon','猛攻重型加特林炮')],title='猛攻加特林炮 Onslaught Gatling Cannon')
save(1244,{2:'惩罚者旋转炮是星际战士西卡然惩罚者坦克使用的武器。',4:'Punisher Rotary Cannon 惩罚者旋转炮',6:'在复杂的供弹系统和陀螺辅助后坐力补偿器支持下，惩罚者旋转炮能够持续倾泻大口径炮弹。虽然每发炮弹不过是实心碳化铁弹丸，但极高的射速已足以摧毁密集步兵编队或轻型载具。'},terms=[('Punisher Rotary Cannon','惩罚者旋转炮')])
